CREATE OR REPLACE FUNCTION private.delayed_capture_reviews()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE a jsonb; e uuid; o private.delayed_outcomes; move jsonb;
BEGIN
 IF TG_OP='UPDATE' AND EXISTS(SELECT FROM private.board_undo_audits WHERE match_id=NEW.id AND mode='async' AND transaction_id=txid_current() AND NEW.revision=(restored_row->>'revision')::bigint) THEN RETURN NEW;END IF;
 IF NEW.game_type<>'ptown-words' THEN
  FOR a IN SELECT value FROM jsonb_array_elements(coalesce(NEW.state->'attempts','[]')) LOOP
   e:=NULL;
   INSERT INTO private.delayed_review_events(child_id,match_id,event_key,kind,actor,round,score,completed_at,receipt)
   VALUES(NEW.id,NEW.match_id,NEW.id||':'||(a->>'actor')||':'||(a->>'round'),'attempt',(a->>'actor')::uuid,
    (a->>'round')::int,(a->>'score')::bigint,to_timestamp((a->>'at')::numeric/1000),
    jsonb_build_object('game',NEW.game_type,'rules',NEW.config,'result',a#>'{board,result}'))
   ON CONFLICT(event_key) DO NOTHING RETURNING id INTO e;
   IF e IS NOT NULL THEN INSERT INTO private.delayed_review_boards VALUES(e,private.delayed_review_board(NEW.game_type,a->'board'));END IF;
  END LOOP;
 ELSIF OLD.state->>'turn' IS DISTINCT FROM NEW.state->>'turn' THEN
  move:=NEW.state->'moves'->-1;
  IF move IS NOT NULL THEN
   INSERT INTO private.delayed_review_events(child_id,match_id,event_key,kind,actor,round,score,completed_at,receipt)
   VALUES(NEW.id,NEW.match_id,NEW.id||':word:'||(move->>'turn')||coalesce(':'||(NEW.state->>'adminUndoId'),''),'attempt',(move->>'playerId')::uuid,
    (move->>'turn')::int,(move->>'points')::bigint,clock_timestamp(),jsonb_build_object('game',NEW.game_type,'rules',NEW.config,'move',move))
   ON CONFLICT(event_key) DO NOTHING RETURNING id INTO e;
   IF e IS NOT NULL THEN INSERT INTO private.delayed_review_boards VALUES(e,private.delayed_review_board(NEW.game_type,NEW.state));END IF;
  END IF;
 END IF;
 IF NEW.terminal AND NOT OLD.terminal THEN
  SELECT * INTO STRICT o FROM private.delayed_current_outcomes WHERE child_id=NEW.id;
  INSERT INTO private.delayed_review_events(child_id,match_id,event_key,kind,actor,round,score,completed_at,receipt)
  VALUES(NEW.id,NEW.match_id,NEW.id||':final'||coalesce((SELECT ':'||id::text FROM private.delayed_effective_child_corrections WHERE child_id=NEW.id),''),'child',NULL,0,NULL,o.completed_at,
   jsonb_build_object('game',NEW.game_type,'rules',NEW.config,'reason',o.reason,'winner',o.winner,
    'organizerDelta',o.organizer_delta,'opponentDelta',o.opponent_delta,'stake',NEW.stake))
  ON CONFLICT(event_key) DO NOTHING;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.delayed_expire(child uuid, expected_segment bigint, expected_expiry timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE c private.delayed_children; m private.delayed_matches;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(731907241);
 SELECT * INTO STRICT m FROM private.delayed_matches WHERE id=(SELECT match_id FROM private.delayed_children WHERE id=child) FOR UPDATE;
 SELECT * INTO STRICT c FROM private.delayed_children WHERE id=child FOR UPDATE;
 IF c.game_type='chess' AND NOT m.real_money THEN RETURN false; END IF;
 IF c.game_type='five-alive' THEN RETURN private.five_alive_async_expire(c,m,expected_segment,expected_expiry); END IF;
 -- An entered live-rules Words turn is governed solely by its playable deadline.
 IF c.game_type='ptown-words' AND c.config->>'version' IN ('ptown-words/2','ptown-words/4') AND c.gameplay_due_at IS NOT NULL THEN
  IF m.status<>'active' OR c.terminal OR private.delayed_held(m.id) OR c.segment<>expected_segment
     OR c.expires_at IS DISTINCT FROM expected_expiry OR clock_timestamp()<c.gameplay_due_at THEN RETURN false; END IF;
  PERFORM private.delayed_words_finish_turn(c,private.ptown_words_reduce(c.state,'tick',NULL,(c.state->>'deadline')::bigint),clock_timestamp());
  RETURN true;
 END IF;
 IF m.status<>'active' OR c.terminal OR private.delayed_held(m.id) OR c.segment<>expected_segment OR c.expires_at IS DISTINCT FROM expected_expiry
  OR c.expires_at IS NULL OR clock_timestamp()<c.expires_at THEN RETURN false; END IF;
 -- An earlier active-game deadline must be resolved by the game adapter first.
 IF c.gameplay_due_at IS NOT NULL AND c.gameplay_due_at<c.expires_at THEN RETURN false; END IF;
 IF c.game_type='chess' THEN
  PERFORM private.chess_sync('async',c.id);RETURN (SELECT terminal FROM private.delayed_children WHERE id=c.id);
 ELSIF c.game_type='ptown-words' THEN
  IF c.config->>'version'='ptown-words/3' THEN
   PERFORM private.delayed_words_finish_turn(c,private.ptown_words_reduce(c.state,'pass',NULL,(c.state->>'deadline')::bigint-1),clock_timestamp());
  ELSE
   PERFORM private.delayed_words_finish_turn(c,private.ptown_words_reduce(c.state,'tick',NULL,greatest((c.state->>'deadline')::bigint,floor(extract(epoch FROM clock_timestamp())*1000)::bigint)),clock_timestamp());
  END IF;
  RETURN true;
 ELSIF c.game_type='quintzee' THEN
  IF c.gameplay_due_at IS NOT NULL THEN RETURN false;END IF;
  PERFORM private.delayed_quintzee_missed_turn(c,m);RETURN true;
 END IF;
 PERFORM private.delayed_record_outcome(c.id,c.revision,'timeout_forfeit',CASE WHEN c.actor=m.organizer THEN m.opponent ELSE m.organizer END,
  jsonb_build_object('segment',c.segment,'expiredAt',c.expires_at,'actor',c.actor));
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION private.delayed_finalize(parent uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE financial_id uuid; m private.delayed_matches; receipt private.delayed_settlements; n integer; completed integer;
 net_i bigint; hash text; a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); dg uuid:=gen_random_uuid(); result_id uuid:=gen_random_uuid(); changes jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(731907241);
 SELECT * INTO STRICT m FROM private.delayed_matches WHERE id=parent FOR UPDATE;
 SELECT coalesce((SELECT financial_game_id FROM private.delayed_current_corrections WHERE match_id=parent),parent) INTO financial_id;
 SELECT * INTO receipt FROM private.delayed_current_settlements WHERE match_id=parent;
 IF FOUND THEN RETURN to_jsonb(receipt); END IF;
 IF m.status<>'active' OR private.delayed_held(parent) THEN RAISE EXCEPTION 'delayed:not_settleable'; END IF;
 SELECT count(*) INTO n FROM private.delayed_children WHERE match_id=parent;
 SELECT count(*),coalesce(sum(o.organizer_delta),0),md5(coalesce(jsonb_agg(to_jsonb(o) ORDER BY c.ordinal)::text,''))
  INTO completed,net_i,hash FROM private.delayed_children c JOIN private.delayed_current_outcomes o ON o.child_id=c.id AND o.match_id=c.match_id
  WHERE c.match_id=parent AND c.terminal;
 IF n=0 OR n<>jsonb_array_length(m.offer) OR completed<>n THEN RETURN NULL; END IF;
 IF abs(net_i)>2147483647 THEN RAISE EXCEPTION 'delayed:amount_overflow'; END IF;
 INSERT INTO public.games(id,name,game_type,status,current_host,real_money,pot,buy_in)
  VALUES(financial_id,'Delayed Head-to-Head','delayed-head-to-head','game_over',m.organizer,m.real_money,0,0);
 INSERT INTO public.dealer_games(id,session_id,dealer_user_id,game_type,config)
  VALUES(dg,financial_id,m.organizer,'delayed-head-to-head',jsonb_build_object('offerHash',m.offer_hash,'policy',m.policy_version));
 UPDATE public.games SET current_game_uuid=dg WHERE id=financial_id;
 INSERT INTO public.players(id,game_id,user_id,position,chips,status,is_bot,sitting_out,waiting)
  VALUES(a,financial_id,m.organizer,1,0,'active',false,false,false),(b,financial_id,m.opponent,2,0,'active',false,false,false);
 changes:=jsonb_build_object(a::text,net_i,b::text,-net_i);
 INSERT INTO public.game_results(id,game_id,dealer_game_id,hand_number,settlement_key,game_type,
  winner_player_id,winner_username,winning_hand_description,pot_won,player_chip_changes,is_chopped)
 VALUES(result_id,financial_id,dg,1,'delayed_parent','delayed-head-to-head',CASE WHEN net_i>0 THEN a WHEN net_i<0 THEN b END,
  CASE WHEN net_i=0 THEN 'Tie' ELSE (SELECT username FROM public.profiles WHERE id=CASE WHEN net_i>0 THEN m.organizer ELSE m.opponent END) END,
  'Delayed match aggregate',abs(net_i)::integer,changes,net_i=0);
 IF net_i<>0 THEN
  PERFORM public.settle_gameplay_chip_transfers(financial_id,jsonb_build_array(jsonb_build_object(
   'from',jsonb_build_object('kind','player','playerId',CASE WHEN net_i>0 THEN b ELSE a END),
   'to',jsonb_build_object('kind','player','playerId',CASE WHEN net_i>0 THEN a ELSE b END),'amount',abs(net_i)::integer)),'win');
 END IF;
 INSERT INTO public.session_player_snapshots(game_id,dealer_game_id,hand_number,player_id,user_id,username,chips,is_bot)
 SELECT financial_id,dg,1,p.id,p.user_id,pr.username,p.chips,false FROM public.players p JOIN public.profiles pr ON pr.id=p.user_id WHERE p.game_id=financial_id;
 -- record_session_results owns account posting from these final snapshots.
 UPDATE public.games SET status='session_ended',session_ended_at=clock_timestamp(),game_over_at=clock_timestamp(),pending_session_end=false WHERE id=financial_id;
 IF m.real_money AND ((SELECT count(*) FROM public.player_transactions WHERE source_game_id=financial_id AND transaction_type='SessionResult')<>2
  OR NOT EXISTS(SELECT FROM public.player_transactions WHERE source_game_id=financial_id AND profile_id=m.organizer AND transaction_type='SessionResult' AND player_transactions.amount=net_i)
  OR NOT EXISTS(SELECT FROM public.player_transactions WHERE source_game_id=financial_id AND profile_id=m.opponent AND transaction_type='SessionResult' AND player_transactions.amount=-net_i))
 THEN RAISE EXCEPTION 'delayed:account_posting_mismatch'; END IF;
 IF financial_id<>parent THEN
 INSERT INTO private.delayed_reopened_settlements(match_id,game_id,dealer_game_id,result_id,outcome_hash,child_count,organizer_delta,opponent_delta,generation)
 VALUES(parent,financial_id,dg,result_id,hash,n,net_i,-net_i,(SELECT generation FROM private.delayed_current_corrections WHERE match_id=parent)) RETURNING match_id,game_id,dealer_game_id,private.delayed_reopened_settlements.result_id,outcome_hash,child_count,organizer_delta,opponent_delta,created_at INTO receipt;
 ELSE
 INSERT INTO private.delayed_settlements(match_id,game_id,dealer_game_id,result_id,outcome_hash,child_count,organizer_delta,opponent_delta)
 VALUES(parent,financial_id,dg,result_id,hash,n,net_i,-net_i) RETURNING * INTO receipt;
 END IF;
 UPDATE private.delayed_matches SET status='settled',settled_at=clock_timestamp(),revision=revision+1 WHERE id=parent;
 PERFORM private.delayed_notify(parent);
 RETURN to_jsonb(receipt);
END $function$

CREATE OR REPLACE FUNCTION private.delayed_notify(parent uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE m private.delayed_matches;who uuid;n int;available int;k text;active boolean;p jsonb;seen boolean;
BEGIN
 PERFORM private.delayed_notify_before_reviews(parent);
 SELECT * INTO STRICT m FROM private.delayed_matches WHERE id=parent;
 IF EXISTS(SELECT FROM private.delayed_removals WHERE match_id=parent) THEN RETURN;END IF;
 IF EXISTS(SELECT FROM private.delayed_children WHERE match_id=parent AND private.five_alive_or_actor(delayed_children,m.organizer) AND NOT terminal) THEN
  INSERT INTO private.delayed_acceptance_retired VALUES(parent) ON CONFLICT DO NOTHING;
 END IF;
 FOREACH who IN ARRAY ARRAY[m.organizer,m.opponent] LOOP
  SELECT count(*) INTO available FROM private.delayed_children WHERE match_id=parent AND private.five_alive_or_actor(delayed_children,who) AND NOT terminal;
  SELECT count(*) INTO n FROM private.delayed_current_review_events e WHERE e.match_id=parent AND kind='child' AND NOT EXISTS(SELECT FROM private.delayed_review_seen s WHERE s.event_id=e.id AND s.viewer=who);
  FOREACH k IN ARRAY ARRAY['accepted','results','settled'] LOOP
   active:=CASE k WHEN 'accepted' THEN who=m.organizer AND m.status='active' AND available=0 AND NOT EXISTS(SELECT FROM private.delayed_acceptance_retired WHERE match_id=parent)
    WHEN 'results' THEN m.status='active' AND n>0
    ELSE m.status='settled' AND NOT EXISTS(SELECT FROM private.delayed_current_finale_seen WHERE match_id=parent AND viewer=who) END;
   p:=jsonb_build_object('status',m.status,'opponentId',CASE WHEN who=m.organizer THEN m.opponent ELSE m.organizer END,
    'opponentName',(SELECT username FROM public.profiles WHERE id=CASE WHEN who=m.organizer THEN m.opponent ELSE m.organizer END),'completionCount',n,'availableCount',available);
   INSERT INTO public.platform_notifications(user_id,match_id,kind,actionable,payload) VALUES(who,parent,k,active,p)
   ON CONFLICT(user_id,match_id,kind) DO UPDATE SET actionable=EXCLUDED.actionable,payload=EXCLUDED.payload,revision=platform_notifications.revision+1,updated_at=clock_timestamp()
    WHERE (platform_notifications.actionable,platform_notifications.payload) IS DISTINCT FROM (EXCLUDED.actionable,EXCLUDED.payload);
  END LOOP;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION private.delayed_record_outcome(child uuid, expected_revision bigint, reason_i text, winner_i uuid, evidence_i jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE c private.delayed_children; m private.delayed_matches; old private.delayed_outcomes; delta_i integer;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(731907241);
 SELECT * INTO STRICT m FROM private.delayed_matches WHERE id=(SELECT match_id FROM private.delayed_children WHERE id=child) FOR UPDATE;
 SELECT * INTO STRICT c FROM private.delayed_children WHERE id=child FOR UPDATE;
 SELECT * INTO old FROM private.delayed_current_outcomes WHERE child_id=child;
 IF FOUND THEN
  IF (old.terminal_revision,old.reason,old.winner,old.evidence) IS DISTINCT FROM (expected_revision,reason_i,winner_i,evidence_i)
  THEN RAISE EXCEPTION 'delayed:outcome_conflict'; END IF;
  RETURN to_jsonb(old);
 END IF;
 IF m.status<>'active' OR c.terminal OR c.revision IS DISTINCT FROM expected_revision OR private.delayed_held(m.id)
 THEN RAISE EXCEPTION 'delayed:stale_outcome'; END IF;
 IF reason_i IS NULL OR reason_i NOT IN('normal','timeout_forfeit','draw','void') OR evidence_i IS NULL
 OR (reason_i IN('normal','timeout_forfeit') AND (winner_i IS NULL OR winner_i NOT IN(m.organizer,m.opponent)))
 OR (reason_i IN('draw','void') AND winner_i IS NOT NULL) THEN RAISE EXCEPTION 'delayed:invalid_outcome'; END IF;
 IF c.game_type='chess' AND NOT m.real_money AND reason_i='timeout_forfeit' THEN RAISE EXCEPTION 'chess:untimed';END IF;
 delta_i:=CASE WHEN winner_i=m.organizer THEN c.stake WHEN winner_i=m.opponent THEN -c.stake ELSE 0 END;
 IF EXISTS(SELECT FROM private.delayed_effective_child_corrections WHERE child_id=c.id) THEN
 INSERT INTO private.delayed_reopened_outcomes(child_id,match_id,terminal_revision,segment,reason,winner,organizer_delta,opponent_delta,evidence,generation)
 VALUES(c.id,m.id,c.revision,c.segment,reason_i,winner_i,delta_i,-delta_i,evidence_i,(SELECT generation FROM private.delayed_effective_child_corrections WHERE child_id=c.id)) RETURNING child_id,match_id,terminal_revision,segment,reason,winner,organizer_delta,opponent_delta,evidence,completed_at INTO old;
 ELSE
 INSERT INTO private.delayed_outcomes(child_id,match_id,terminal_revision,segment,reason,winner,organizer_delta,opponent_delta,evidence)
 VALUES(c.id,m.id,c.revision,c.segment,reason_i,winner_i,delta_i,-delta_i,evidence_i) RETURNING * INTO old;
 END IF;
 UPDATE private.delayed_children SET terminal=true,revision=revision+1 WHERE id=c.id;
 UPDATE private.delayed_matches SET revision=revision+1 WHERE id=m.id;
 PERFORM private.delayed_finalize(m.id);
 PERFORM private.delayed_notify(m.id);
 RETURN to_jsonb(old);
END $function$

CREATE OR REPLACE FUNCTION private.delayed_tri_project(r jsonb, viewer uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE s jsonb:=r->'state'; a jsonb; p text; paired integer; totals jsonb:='{}'; pending jsonb:='{}';
 own_results jsonb:='[]'; board_i jsonb; total_i bigint; pending_i integer; disclosed boolean;
BEGIN
 IF s IS NULL OR s='null'::jsonb THEN
  s:=jsonb_build_object('players',jsonb_build_array(r->'organizer',r->'opponent'),'round',1,'attempts','[]'::jsonb);
 END IF;
 SELECT min(n) INTO paired FROM (SELECT (SELECT count(*) FROM jsonb_array_elements(s->'attempts') attempt(value) WHERE attempt.value->>'actor'=person.id) n FROM jsonb_array_elements_text(s->'players') person(id)) q;
 FOR p IN SELECT jsonb_array_elements_text(s->'players') LOOP
  total_i:=0;pending_i:=0;
  FOR a IN SELECT value FROM jsonb_array_elements(s->'attempts') LOOP
   IF a->>'actor'<>p THEN CONTINUE;END IF;
   disclosed:=p=viewer::text OR CASE WHEN r ? 'reviewed' THEN (r->'reviewed') ? (p||':'||(a->>'round')) ELSE (r->>'terminal')::boolean OR (a->>'round')::integer<=paired END;
   IF disclosed THEN total_i:=total_i+(a->>'score')::bigint;ELSE pending_i:=pending_i+1;END IF;
  END LOOP;
  totals:=totals||jsonb_build_object(p,total_i);pending:=pending||jsonb_build_object(p,pending_i);
 END LOOP;
 IF r->>'actor'=viewer::text AND nullif(s->'board','null') IS NOT NULL THEN board_i:=public.delayed_tri_core('visible',NULL,0,s->'board');END IF;
 FOR a IN SELECT value FROM jsonb_array_elements(s->'attempts') WHERE value->>'actor'=viewer::text LOOP
  own_results:=own_results||jsonb_build_array(jsonb_build_object('round',a->'round','score',a->'score','at',a->'at','result',a#>'{board,result}','board',public.delayed_tri_core('visible',NULL,0,a->'board')));
 END LOOP;
 RETURN jsonb_build_object('id',r->'id','matchId',r->'match_id','game',r->'game_type','config',r->'config','revision',r->'revision','segment',r->'segment','actor',r->'actor',
  'round',s->'round','board',board_i,'totals',totals,'pendingResults',pending,'reviewRevision',coalesce(jsonb_array_length(r->'reviewed'),0),'terminal',r->'terminal','held',r->'held',
  'expiresAt',r->'expires_at','serverAt',r->'server_at','holeResults','[]'::jsonb,'ownResults',own_results,
  'winner',CASE WHEN (r->>'terminal')::boolean THEN r#>'{outcome,winner}' END,
  'result',CASE WHEN (r->>'terminal')::boolean AND nullif(r->'outcome','null') IS NOT NULL THEN jsonb_build_object('reason',r#>'{outcome,reason}','winner',r#>'{outcome,winner}',
   'delta',CASE WHEN viewer::text=r->>'organizer' THEN r#>'{outcome,organizer_delta}' ELSE r#>'{outcome,opponent_delta}' END) END);
END $function$

CREATE OR REPLACE FUNCTION private.delayed_tri_transition(r jsonb, intent jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE s jsonb:=r->'state'; b jsonb; cfg jsonb:=r->'config';
 at_i bigint:=(r->>'server_at')::bigint; due_i bigint; expiry bigint;
 player text; turn_i integer; round_i integer; score_i bigint; advanced boolean:=false;
 action_i text:=intent->>'type';
BEGIN
 IF s IS NULL OR s='null'::jsonb THEN
  s:=jsonb_build_object('version','delayed/1','game','tri-towers','child',r->'id',
   'players',jsonb_build_array(r->'starter',CASE WHEN r->>'starter'=r->>'organizer' THEN r->'opponent' ELSE r->'organizer' END),
   'round',1,'turn',0,'totals',jsonb_build_object(r->>'organizer',0,r->>'opponent',0),
   'attempts','[]'::jsonb,'board',NULL,'deck',NULL,'completed',false,'winner',NULL,'segmentStartedAt',NULL);
 END IF;
 turn_i:=(s->>'turn')::integer;round_i:=(s->>'round')::integer;player:=s->'players'->>turn_i;
 IF s->>'child' IS DISTINCT FROM r->>'id' OR s->>'game'<>'tri-towers' OR player IS DISTINCT FROM r->>'actor' OR (s->>'completed')::boolean THEN RAISE EXCEPTION 'delayed:identity';END IF;
 b:=nullif(s->'board','null');due_i:=(b->>'deadline')::bigint;
 expiry:=floor(extract(epoch FROM (r->>'expires_at')::timestamptz)*1000)::bigint;
 IF at_i>=expiry AND (due_i IS NULL OR expiry<=due_i) THEN
  RETURN jsonb_build_object('state',s,'advanced',false,'at',expiry);
 END IF;
 IF due_i IS NOT NULL AND at_i>=due_i THEN
  at_i:=due_i;b:=public.delayed_tri_core('reduce',cfg,0,b,'tick',NULL,at_i);
 ELSIF action_i='tick' THEN RETURN jsonb_build_object('state',s,'advanced',false,'at',at_i);
 ELSIF action_i='start' THEN
  IF b IS NOT NULL THEN RAISE EXCEPTION 'delayed:already_started';END IF;
  b:=public.delayed_tri_core('deal',cfg,(s->'totals'->>player)::bigint,NULL,NULL,NULL,at_i);
  s:=jsonb_set(s,'{segmentStartedAt}',to_jsonb(at_i));
 ELSE
  IF b IS NULL THEN RAISE EXCEPTION 'delayed:not_started';END IF;
  IF action_i NOT IN('remove','draw','take_score') THEN RAISE EXCEPTION 'delayed:invalid_action';END IF;
  b:=public.delayed_tri_core('reduce',cfg,0,b,action_i,(intent->>'index')::integer,at_i);
 END IF;
 s:=jsonb_set(s,'{board}',b);
 IF b->>'phase'='stage_complete' THEN
  score_i:=(b->>'score')::bigint-(s->'totals'->>player)::bigint;
  s:=jsonb_set(s,ARRAY['totals',player],to_jsonb((b->>'score')::bigint));
  s:=jsonb_set(s,'{attempts}',(s->'attempts')||jsonb_build_array(jsonb_build_object('actor',player,'round',round_i,'score',score_i,'at',at_i,'board',b)));
  s:=s||jsonb_build_object('board',NULL,'deck',NULL,'segmentStartedAt',NULL);
  advanced:=true;turn_i:=turn_i+1;IF turn_i=2 THEN turn_i:=0;round_i:=round_i+1;END IF;
  WHILE round_i>(cfg->>'stages')::integer LOOP
   IF round_i>(cfg->>'stages')::integer+(cfg->>'maxBonusStages')::integer THEN s:=jsonb_set(s,'{completed}','true');EXIT;END IF;
   EXIT WHEN public.delayed_tri_core('eligible',cfg,(s->'totals'->>(s->'players'->>turn_i))::bigint)='true'::jsonb;
   turn_i:=turn_i+1;IF turn_i=2 THEN turn_i:=0;round_i:=round_i+1;END IF;
  END LOOP;
  s:=s||jsonb_build_object('turn',turn_i,'round',round_i);
  IF (s->>'completed')::boolean THEN
   s:=jsonb_set(s,'{winner}',coalesce(CASE
    WHEN (s->'totals'->>(s->'players'->>0))::bigint>(s->'totals'->>(s->'players'->>1))::bigint THEN s->'players'->0
    WHEN (s->'totals'->>(s->'players'->>1))::bigint>(s->'totals'->>(s->'players'->>0))::bigint THEN s->'players'->1 END,'null'::jsonb));
  END IF;
 END IF;
 RETURN jsonb_build_object('state',s,'advanced',advanced,'at',at_i);
END $function$

CREATE OR REPLACE FUNCTION private.delayed_turn_window()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 IF NEW.game_type='chess' AND NOT NEW.terminal AND EXISTS(SELECT FROM private.delayed_matches WHERE id=NEW.match_id AND NOT real_money) THEN
  NEW.state:=private.chess_untimed_state(NEW.state); NEW.available_at:=NULL;NEW.last_call_at:=NULL;NEW.expires_at:=NULL;NEW.started_at:=NULL;NEW.gameplay_due_at:=NULL;
  RETURN NEW;
 END IF;
 IF NOT NEW.terminal AND NEW.available_at IS NOT NULL THEN
  NEW.last_call_at:=NEW.available_at+interval '48 hours';
  NEW.expires_at:=NEW.available_at+interval '72 hours';
  IF NEW.game_type='chess' AND NEW.gameplay_due_at IS NULL AND NEW.state->>'opened'='false' THEN
   NEW.state:=NEW.state||jsonb_build_object('deadline',floor(extract(epoch FROM NEW.expires_at)*1000)::bigint,'clockDuration',259200000);
  ELSIF NEW.game_type='ptown-words' AND NEW.config->>'version'='ptown-words/3' THEN
   NEW.state:=jsonb_set(NEW.state,'{deadline}',to_jsonb(floor(extract(epoch FROM NEW.expires_at)*1000)::bigint));
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.optional_bonus_async_offer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor text;
BEGIN
 IF coalesce(OLD.state->>'round','1')<>'3' AND NEW.state->>'round'='3'
    AND EXISTS(SELECT FROM private.delayed_matches WHERE id=NEW.match_id AND real_money) THEN
  actor:=private.optional_bonus_async_actor(NEW.game_type,NEW.config,NEW.state);
  IF actor IS NOT NULL AND actor=NEW.actor::text THEN
   NEW.state:=NEW.state||jsonb_build_object('optionalBonus',jsonb_build_object('actor',actor,'choice','pending'));
  END IF;
 ELSIF NEW.state#>>'{optionalBonus,choice}'='pending' AND nullif(NEW.state->'board','null') IS NOT NULL THEN
  -- Backward-compatible Start from an older client is an explicit Play choice.
  NEW.state:=jsonb_set(NEW.state,'{optionalBonus,choice}','"play"');
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.delayed_board_action(p_child uuid, p_actor uuid, p_game text, p_request uuid, p_revision bigint, p_segment bigint, p_intent jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 r jsonb; s jsonb; board jsonb; reduced jsonb; committed jsonb; visible jsonb;
 saved jsonb; own_boards jsonb:='[]'; items integer[]; action text:=p_intent->>'type';
 fingerprint jsonb:=jsonb_build_object('child',p_child,'revision',p_revision,'segment',p_segment,'intent',p_intent);
 at_ms bigint;
BEGIN
 IF p_actor IS NULL OR p_request IS NULL OR p_revision IS NULL OR p_segment IS NULL
    OR p_game IS NULL OR p_game NOT IN('take-two','quintzee','boxdrop') THEN RAISE EXCEPTION 'delayed:invalid_request'; END IF;
 PERFORM pg_advisory_xact_lock_shared(731907241);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_actor::text||p_request::text,319));
 r:=public.delayed_load(p_child,p_actor,p_request);
 IF r->>'game_type' IS DISTINCT FROM p_game THEN RAISE EXCEPTION 'delayed:wrong_game'; END IF;
 s:=r->'state'; board:=s->'board'; at_ms:=(r->>'server_at')::bigint;
 IF nullif(r->'receipt','null') IS NOT NULL OR (r->>'held')::boolean OR (r->>'terminal')::boolean
    OR r->>'actor' IS DISTINCT FROM p_actor::text OR (r->>'revision')::bigint<>p_revision OR (r->>'segment')::bigint<>p_segment
    OR nullif(board,'null') IS NULL OR least((board->>'deadline')::bigint,floor(extract(epoch FROM (r->>'expires_at')::timestamptz)*1000)::bigint)<=at_ms
 THEN RETURN jsonb_build_object('fallback',true); END IF;
 IF s->>'child' IS DISTINCT FROM p_child::text OR s->>'game' IS DISTINCT FROM p_game
    OR s->'players'->>((s->>'turn')::integer) IS DISTINCT FROM p_actor::text OR (s->>'completed')::boolean THEN RAISE EXCEPTION 'delayed:identity'; END IF;
 IF action IS NULL OR NOT (CASE p_game WHEN 'take-two' THEN action IN('pair','draw','take_score')
  WHEN 'quintzee' THEN action IN('roll','score','score_zero') ELSE action IN('place','recycle','take_score') END)
 THEN RAISE EXCEPTION 'delayed:invalid_action'; END IF;
 IF p_intent ? 'items' THEN
  IF jsonb_typeof(p_intent->'items')<>'array' OR jsonb_array_length(p_intent->'items')>5 THEN RAISE EXCEPTION 'delayed:invalid_items';END IF;
  IF EXISTS(SELECT FROM jsonb_array_elements(p_intent->'items') i WHERE jsonb_typeof(i)<>'number' OR i::text !~ '^-?[0-9]+$'
    OR i::text::numeric NOT BETWEEN (CASE WHEN action='pair' THEN -1 ELSE 0 END) AND (CASE WHEN action='pair' THEN 32 ELSE 2147483647 END)) THEN RAISE EXCEPTION 'delayed:invalid_items'; END IF;
  items:=ARRAY(SELECT value::integer FROM jsonb_array_elements_text(p_intent->'items') WITH ORDINALITY ORDER BY ordinality);
 ELSIF action IN('pair','roll','score','score_zero','place','recycle') THEN RAISE EXCEPTION 'delayed:invalid_items'; END IF;
 IF action='pair' AND (cardinality(items)<>2 OR items[1]=items[2]) THEN RAISE EXCEPTION 'delayed:invalid_items'; END IF;
 IF p_game='take-two' THEN
  reduced:=public.delayed_take_two_core(p_child,'reduce',(s->>'round')::int,(s->'totals'->>p_actor::text)::bigint,board,action,items,at_ms);
 ELSE
  reduced:=public.delayed_board_core(p_game,'reduce',r->'config',(s->'totals'->>p_actor::text)::bigint,board,action,items,at_ms);
 END IF;
 -- Reuse this exact roll/deal at a stage boundary. The existing adapter owns
 -- advancement, bonuses, authoritative settlement and revision conflict recovery.
 IF reduced->>'phase'='stage_complete' THEN RETURN jsonb_build_object('boundary',r,'reduced',reduced); END IF;
 committed:=public.delayed_commit(p_child,p_actor,p_revision,jsonb_set(s,'{board}',reduced),'action',at_ms,false,p_request,fingerprint);
 IF committed->>'outcome'<>'committed' THEN RETURN jsonb_build_object('fallback',true); END IF;
 r:=(committed->'record')||jsonb_build_object('reviewed',r->'reviewed');
 IF p_game='take-two' THEN visible:=public.delayed_take_two_core(p_child,'visible',p_board=>reduced);
 ELSE visible:=public.delayed_board_core(p_game,'visible',p_board=>reduced); END IF;
 FOR saved IN SELECT value->'board' FROM jsonb_array_elements(s->'attempts') WHERE value->>'actor'=p_actor::text LOOP
  own_boards:=own_boards||jsonb_build_array(CASE WHEN p_game='take-two' THEN public.delayed_take_two_core(p_child,'visible',p_board=>saved)
   ELSE public.delayed_board_core(p_game,'visible',p_board=>saved) END);
 END LOOP;
 RETURN jsonb_build_object('record',r,'visible',visible,'ownBoards',own_boards);
END $function$

CREATE OR REPLACE FUNCTION public.delayed_bonus_choice(p_child uuid, p_actor uuid, p_request uuid, p_revision bigint, p_segment bigint, p_choice text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r jsonb;s jsonb;fingerprint jsonb;at_ms bigint;committed jsonb;
BEGIN
 IF p_actor IS NULL OR p_request IS NULL OR p_revision IS NULL OR p_segment IS NULL OR p_choice IS NULL OR p_choice NOT IN('play','skip') THEN RAISE EXCEPTION 'bonus:invalid_command';END IF;
 PERFORM pg_advisory_xact_lock_shared(731907241);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_actor::text||p_request::text,319));
 r:=public.delayed_load(p_child,p_actor,p_request);s:=r->'state';at_ms:=(r->>'server_at')::bigint;
 fingerprint:=jsonb_build_object('child',p_child,'revision',p_revision,'segment',p_segment,'intent',jsonb_build_object('type','bonus_'||p_choice));
 IF nullif(r->'receipt','null') IS NOT NULL THEN
  IF r#>>'{receipt,child_id}' IS DISTINCT FROM p_child::text OR r#>'{receipt,fingerprint}' IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'delayed:request_conflict';END IF;
  RETURN r;
 END IF;
 IF (r->>'held')::boolean OR (r->>'terminal')::boolean OR r->>'actor' IS DISTINCT FROM p_actor::text
  OR (r->>'revision')::bigint<>p_revision OR (r->>'segment')::bigint<>p_segment THEN RAISE EXCEPTION 'delayed:stale_action';END IF;
 IF at_ms>=floor(extract(epoch FROM (r->>'expires_at')::timestamptz)*1000) THEN RAISE EXCEPTION 'bonus:deadline';END IF;
 IF NOT EXISTS(SELECT FROM private.delayed_matches WHERE id=(r->>'match_id')::uuid AND real_money AND status='active')
  OR s#>>'{optionalBonus,choice}' IS DISTINCT FROM 'pending' OR s#>>'{optionalBonus,actor}' IS DISTINCT FROM p_actor::text
  OR private.optional_bonus_async_actor(r->>'game_type',r->'config',s) IS DISTINCT FROM p_actor::text THEN RAISE EXCEPTION 'bonus:not_eligible' USING ERRCODE='42501';END IF;
 s:=jsonb_set(s,'{optionalBonus,choice}',to_jsonb(p_choice));
 IF p_choice='skip' THEN s:=s||jsonb_build_object('completed',true,'winner',p_actor);END IF;
 -- Existing commit owns immutable outcome, actual finances, notices and archival.
 -- Play preserves segment/availability/deadline. Skip adds no synthetic attempt.
 committed:=public.delayed_commit(p_child,p_actor,p_revision,s,'action',at_ms,p_choice='skip',p_request,fingerprint);
 IF committed->>'outcome' NOT IN('committed','duplicate') THEN RAISE EXCEPTION 'delayed:stale_action';END IF;
 RETURN committed->'record';
END $function$

CREATE OR REPLACE FUNCTION public.delayed_commit(p_child uuid, p_actor uuid, p_revision bigint, p_state jsonb, p_event text, p_at bigint, p_advanced boolean, p_request uuid DEFAULT NULL::uuid, p_fingerprint jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c private.delayed_children;m private.delayed_matches;r private.delayed_commands;now_i timestamptz;event_time timestamptz;
 done boolean;next_actor uuid;next_due bigint;expected_due timestamptz;
BEGIN
 IF p_actor IS NOT NULL THEN PERFORM private.require_account_enabled(p_actor); END IF;
 PERFORM private.delayed_words_check_health();
 PERFORM pg_advisory_xact_lock_shared(731907241);
 IF p_actor IS NOT NULL AND p_request IS NOT NULL THEN
  PERFORM pg_advisory_xact_lock(hashtextextended(p_actor::text||p_request::text,319));
 END IF;
 SELECT * INTO STRICT m FROM private.delayed_matches WHERE id=(SELECT match_id FROM private.delayed_children WHERE id=p_child) FOR UPDATE;
 SELECT * INTO STRICT c FROM private.delayed_children WHERE id=p_child FOR UPDATE;
 IF p_actor IS NOT NULL THEN
  PERFORM private.delayed_actor(p_actor);
  IF p_actor NOT IN(m.organizer,m.opponent) THEN RAISE EXCEPTION 'delayed:not_authorized' USING ERRCODE='42501';END IF;
 END IF;
 IF c.game_type NOT IN('run21','tri-towers','quintzee','boxdrop','mega-card-golf','take-two','crib-lab','chucky-showdown') OR EXISTS(SELECT FROM private.delayed_removals WHERE match_id=m.id) THEN RAISE EXCEPTION 'delayed:removed_or_unavailable';END IF;
 IF p_request IS NOT NULL THEN
  SELECT * INTO r FROM private.delayed_commands WHERE actor=p_actor AND request_id=p_request;
  IF FOUND THEN
   IF r.child_id IS DISTINCT FROM p_child OR r.fingerprint IS DISTINCT FROM p_fingerprint THEN RAISE EXCEPTION 'delayed:request_conflict'; END IF;
   RETURN jsonb_build_object('outcome','duplicate','record',private.delayed_child_record(c));
  END IF;
 END IF;
 IF c.revision IS DISTINCT FROM p_revision OR c.terminal THEN RETURN jsonb_build_object('outcome','conflict','record',private.delayed_child_record(c)); END IF;
 IF m.status<>'active' OR private.delayed_held(m.id) THEN RAISE EXCEPTION 'delayed:held';END IF;
 now_i:=clock_timestamp();event_time:=to_timestamp(p_at/1000.0);
 expected_due:=CASE WHEN c.game_type='quintzee' THEN coalesce(c.gameplay_due_at,c.expires_at) ELSE least(c.expires_at,c.gameplay_due_at) END;
 IF p_event='action' THEN
  IF p_actor IS DISTINCT FROM c.actor OR p_request IS NULL OR p_fingerprint IS NULL THEN RAISE EXCEPTION 'delayed:not_your_turn';END IF;
  IF now_i>=expected_due THEN RETURN jsonb_build_object('outcome','deadline','record',private.delayed_child_record(c)); END IF;
 ELSIF p_event='tick' THEN
  IF p_request IS NOT NULL OR now_i<expected_due OR abs(extract(epoch FROM expected_due)*1000-p_at)>=1 THEN RAISE EXCEPTION 'delayed:invalid_tick'; END IF;
  IF c.expires_at<=coalesce(c.gameplay_due_at,c.expires_at) AND NOT(c.game_type='quintzee' AND c.gameplay_due_at IS NOT NULL) THEN
   PERFORM private.delayed_expire(c.id,c.segment,c.expires_at);
   SELECT * INTO c FROM private.delayed_children WHERE id=p_child;
   RETURN jsonb_build_object('outcome','committed','record',private.delayed_child_record(c));
  END IF;
 ELSE RAISE EXCEPTION 'delayed:invalid_event';END IF;
 IF event_time>now_i OR event_time<c.available_at-interval '1 millisecond' OR p_state->>'version' IS DISTINCT FROM 'delayed/1'
  OR p_state->>'child' IS DISTINCT FROM c.id::text OR p_state->>'game' IS DISTINCT FROM c.game_type
  OR p_advanced IS NULL THEN RAISE EXCEPTION 'delayed:invalid_state';END IF;
 done:=coalesce((p_state->>'completed')::boolean,false);
 next_actor:=(p_state->'players'->>(p_state->>'turn')::integer)::uuid;
 IF next_actor IS NULL OR next_actor NOT IN(m.organizer,m.opponent) OR (NOT p_advanced AND next_actor<>c.actor) OR (done AND NOT p_advanced)
 THEN RAISE EXCEPTION 'delayed:invalid_actor';END IF;
 next_due:=CASE WHEN c.game_type IN('crib-lab','chucky-showdown') THEN (p_state#>>'{board,nextDue}')::bigint ELSE (p_state#>>'{board,deadline}')::bigint END;
 UPDATE private.delayed_children SET state=p_state,revision=revision+1,
  actor=next_actor,segment=segment+CASE WHEN p_advanced THEN 1 ELSE 0 END,
  available_at=CASE WHEN p_advanced THEN event_time ELSE available_at END,
  last_call_at=CASE WHEN p_advanced THEN event_time+interval '24 hours' ELSE last_call_at END,
  expires_at=CASE WHEN p_advanced THEN event_time+interval '36 hours' ELSE expires_at END,
  started_at=to_timestamp((p_state->>'segmentStartedAt')::bigint/1000.0),gameplay_due_at=to_timestamp(next_due/1000.0)
 WHERE id=c.id RETURNING * INTO c;
 IF done THEN
  PERFORM private.delayed_record_outcome(c.id,c.revision,CASE WHEN p_state->>'winner' IS NULL THEN 'draw' ELSE 'normal' END,
   (p_state->>'winner')::uuid,jsonb_build_object('rules',c.config,'finalState',p_state));
 ELSE
  UPDATE private.delayed_matches SET revision=revision+1 WHERE id=m.id;
  PERFORM private.delayed_notify(m.id);
 END IF;
 SELECT * INTO c FROM private.delayed_children WHERE id=p_child;
 IF p_request IS NOT NULL THEN INSERT INTO private.delayed_commands VALUES(p_actor,p_request,p_child,p_fingerprint,c.revision);END IF;
 RETURN jsonb_build_object('outcome','committed','record',private.delayed_child_record(c));
END $function$

CREATE OR REPLACE FUNCTION public.delayed_create(p_request uuid, p_opponent uuid, p_real_money boolean, p_lineup jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor_i uuid:=auth.uid(); receipt private.delayed_requests; fingerprint jsonb; parent uuid:=gen_random_uuid(); item jsonb; i integer:=0;
 cfg jsonb; frozen jsonb:='[]';
BEGIN
 PERFORM pg_advisory_xact_lock_shared(731907241);
 PERFORM private.delayed_actor(actor_i);
 fingerprint:=jsonb_build_object('op','create','opponent',p_opponent,'realMoney',p_real_money,'lineup',p_lineup);
 IF p_request IS NULL THEN RAISE EXCEPTION 'delayed:request_required'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(actor_i::text||p_request::text,317));
 SELECT * INTO receipt FROM private.delayed_requests WHERE delayed_requests.actor=actor_i AND request_id=p_request;
 IF FOUND THEN IF receipt.fingerprint IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'delayed:request_conflict'; END IF; RETURN receipt.match_id; END IF;
 PERFORM private.delayed_actor(p_opponent);
 IF actor_i=p_opponent OR p_real_money IS NULL OR jsonb_typeof(p_lineup) IS DISTINCT FROM 'array' OR jsonb_array_length(p_lineup) NOT BETWEEN 1 AND 32
 THEN RAISE EXCEPTION 'delayed:invalid_offer'; END IF;
 IF NOT private.delayed_multi_enabled() AND (jsonb_array_length(p_lineup)<>1 OR p_lineup->0->>'game'<>'ptown-words') THEN RAISE EXCEPTION 'delayed:scope_closed';END IF;
 IF p_real_money AND NOT EXISTS(SELECT FROM private.delayed_release WHERE singleton AND real_qualified) THEN RAISE EXCEPTION 'delayed:real_money_closed';END IF;
 IF NOT EXISTS(SELECT FROM private.delayed_release WHERE singleton AND admission_enabled) THEN RAISE EXCEPTION 'delayed:admission_closed'; END IF;
 IF EXISTS(SELECT FROM public.system_settings WHERE key='maintenance_mode' AND value->>'enabled'='true') THEN RAISE EXCEPTION 'delayed:maintenance'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_lineup) LOOP
  IF coalesce(item->>'game','') NOT IN('five-alive','chess','ptown-words','run21','tri-towers','quintzee','boxdrop','mega-card-golf','take-two','crib-lab','chucky-showdown') OR coalesce(item->>'stake','') !~ '^[1-9][0-9]{0,3}$'
   OR (item-ARRAY['game','stake','config'])<>'{}'::jsonb OR jsonb_typeof(item)<>'object' THEN RAISE EXCEPTION 'delayed:invalid_child'; END IF;
  CASE item->>'game'
  WHEN 'chess' THEN
   IF NOT private.chess_actor_allowed(auth.uid()) OR NOT private.chess_actor_allowed(p_opponent) OR NOT EXISTS(SELECT FROM private.chess_release WHERE singleton AND enabled AND admission_enabled AND async_enabled AND (NOT p_real_money OR real_qualified)) THEN RAISE EXCEPTION 'chess:async_closed';END IF;
   cfg:=private.chess_rules();
  WHEN 'ptown-words' THEN cfg:=private.ptown_words_rules();
  WHEN 'run21' THEN SELECT config INTO STRICT cfg FROM private.gameplay_rulesets WHERE id='run21/3' AND game='run21';
  WHEN 'tri-towers' THEN cfg:=private.tri_towers_rules();
  WHEN 'quintzee' THEN cfg:=private.quintzee_default_rules();
  WHEN 'boxdrop' THEN cfg:=private.boxdrop_rules();
  WHEN 'crib-lab','chucky-showdown' THEN
   IF NOT EXISTS(SELECT FROM private.originals_release WHERE game=item->>'game' AND async_enabled AND (NOT p_real_money OR async_real_qualified)) THEN RAISE EXCEPTION 'originals:async_closed';END IF;
   cfg:=private.originals_config(item->>'game',CASE WHEN item->>'game'='crib-lab' THEN coalesce((item#>>'{config,sharedDeck}')::boolean,true) ELSE false END);
  WHEN 'five-alive' THEN
   IF NOT EXISTS(SELECT FROM private.five_alive_release WHERE singleton AND async_enabled AND (NOT p_real_money OR async_real_qualified)) THEN RAISE EXCEPTION 'delayed:admission_closed';END IF;
   SELECT config INTO STRICT cfg FROM private.arcade_rulesets WHERE id='five-alive/3' AND game='five-alive';
  WHEN 'take-two' THEN
   IF NOT (SELECT enabled FROM private.delayed_take_two_release WHERE singleton) THEN RAISE EXCEPTION 'delayed:admission_closed';END IF;
   cfg:=private.take_two_rules('take-two/2');
  WHEN 'mega-card-golf' THEN
   IF NOT ((SELECT async_enabled FROM private.mega_competition_release WHERE singleton) OR private.mega_test_async_allowed(actor_i,p_opponent,p_request,NULL,p_real_money)) THEN RAISE EXCEPTION 'delayed:admission_closed';END IF;
   cfg:=private.mega_competition_config(item->'config');END CASE;
  IF item ? 'config' AND item->'config' IS DISTINCT FROM cfg THEN RAISE EXCEPTION 'delayed:unsupported_configuration'; END IF;
  frozen:=frozen||jsonb_build_array(item||jsonb_build_object('config',cfg));
 END LOOP;
 IF EXISTS(SELECT FROM private.mega_test_accounts WHERE user_id IN(actor_i,p_opponent)) THEN
  IF NOT private.mega_test_async_allowed(actor_i,p_opponent,p_request,NULL,p_real_money) OR jsonb_array_length(p_lineup)>4 OR EXISTS(SELECT FROM jsonb_array_elements(p_lineup) x WHERE x->>'game'<>'mega-card-golf') THEN RAISE EXCEPTION 'mega:test_offer_scope';END IF;
  UPDATE private.mega_test_async SET match_id=parent WHERE actor=actor_i AND request_id=p_request AND match_id IS NULL;
 END IF;
 INSERT INTO private.delayed_matches(id,organizer,opponent,real_money,offer,offer_hash)
 VALUES(parent,actor_i,p_opponent,p_real_money,frozen,md5(frozen::text));
 FOR item IN SELECT value FROM jsonb_array_elements(frozen) LOOP
  i:=i+1;INSERT INTO private.delayed_children(match_id,ordinal,game_type,stake,config) VALUES(parent,i,item->>'game',(item->>'stake')::integer,item->'config');
 END LOOP;
 INSERT INTO private.delayed_requests VALUES(actor_i,p_request,fingerprint,parent,jsonb_build_object('id',parent));
 PERFORM private.delayed_notify(parent);
 RETURN parent;
END $function$

CREATE OR REPLACE FUNCTION public.delayed_home(p_match uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE h jsonb;c private.delayed_children;item jsonb;lineup jsonb:='[]';who uuid:=auth.uid();scores jsonb;progress jsonb;pending_counts jsonb;person text;pts bigint;shown bigint;pending_count int;seen_count int;next_round int;required int;f uuid;viewed boolean;
BEGIN
 IF NOT EXISTS(SELECT FROM private.delayed_matches WHERE id=p_match)
  AND EXISTS(SELECT FROM public.delayed_match_updates WHERE match_id=p_match AND user_id=who) THEN
  RAISE EXCEPTION 'delayed:invitation_cancelled' USING ERRCODE='P0002';
 END IF;
 h:=public.delayed_home_before_reviews(p_match);
 FOR item IN SELECT value FROM jsonb_array_elements(h->'lineup') LOOP
  SELECT * INTO STRICT c FROM private.delayed_children WHERE id=(item->>'id')::uuid;
  item:=item||jsonb_build_object('playable',
   h->>'status'='active' AND NOT (h->>'held')::boolean AND NOT c.terminal AND c.actor=who
   AND ((c.game_type='chess' AND NOT (h->>'realMoney')::boolean) OR least(c.expires_at,c.gameplay_due_at)>statement_timestamp()),
   'untimed',c.game_type='chess' AND NOT (h->>'realMoney')::boolean,
   'playableDeadline',least(c.expires_at,c.gameplay_due_at));
  -- Existing lobby ordering, presence and resume links use the current actionable deadline.
  IF (c.game_type='chess' OR c.game_type='ptown-words' AND c.config->>'version' IN ('ptown-words/2','ptown-words/4')) AND c.gameplay_due_at IS NOT NULL THEN
   item:=item||jsonb_build_object('availabilityExpiresAt',c.expires_at,'expiresAt',c.gameplay_due_at,'startedAt',c.started_at,'lastCallAt',NULL);
  END IF;
  SELECT id INTO f FROM private.delayed_current_review_events WHERE child_id=c.id AND kind='child';
  viewed:=f IS NULL OR EXISTS(SELECT FROM private.delayed_review_seen WHERE event_id=f AND viewer=who);
  scores:='{}';progress:='{}';pending_counts:='{}';
  IF c.game_type='chess' THEN scores:=NULL;
  ELSIF c.game_type='ptown-words' THEN
   FOR person IN SELECT jsonb_array_elements_text(jsonb_build_array(h->>'organizer',h->>'opponent')) LOOP
    SELECT count(*) INTO pending_count FROM private.delayed_current_review_events e
     WHERE e.child_id=c.id AND e.kind='attempt' AND e.actor::text=person AND person<>who::text
      AND e.round>(private.delayed_words_reveal_state(c.id,who)->>'boundary')::integer
      AND NOT EXISTS(SELECT FROM private.delayed_review_seen seen WHERE seen.event_id=e.id AND seen.viewer=who);
    IF person=who::text OR c.terminal AND viewed THEN shown:=coalesce((c.state->'scores'->>person)::bigint,0);
    ELSE
     SELECT (b.board->'scores'->>person)::bigint INTO shown
      FROM private.delayed_current_review_events e
      JOIN private.delayed_review_seen seen ON seen.event_id=e.id AND seen.viewer=who
      JOIN private.delayed_review_boards b ON b.event_id=e.id
      WHERE e.child_id=c.id AND e.kind='attempt' AND e.actor::text=person ORDER BY e.round DESC LIMIT 1;
     shown:=(private.delayed_words_reveal_state(c.id,who)#>>ARRAY['scores',person])::bigint;
    END IF;
    scores:=scores||jsonb_build_object(person,shown);
    pending_counts:=pending_counts||jsonb_build_object(person,least(pending_count,1));
   END LOOP;
   -- The latest move itself also carries unviewed points.
   item:=item-'lastMove';
  ELSIF c.game_type='five-alive' THEN
   IF c.state->'fiveAlive' IS NOT NULL THEN
    scores:=jsonb_build_object(c.state#>>'{fiveAlive,players,0}',c.state#>'{fiveAlive,sharedScores,0}',c.state#>>'{fiveAlive,players,1}',c.state#>'{fiveAlive,sharedScores,1}');
   END IF;
  ELSE
   FOR person IN SELECT jsonb_array_elements_text(coalesce(c.state->'players',jsonb_build_array(h->>'organizer',h->>'opponent'))) LOOP
    SELECT coalesce(sum((a->>'score')::bigint),0),coalesce(max((a->>'round')::int),0)+1 INTO pts,next_round FROM jsonb_array_elements(coalesce(c.state->'attempts','[]')) a WHERE a->>'actor'=person;
    SELECT coalesce(sum((a->>'score')::bigint) FILTER(WHERE visible),0),count(*) FILTER(WHERE visible),count(*) FILTER(WHERE NOT visible)
     INTO shown,seen_count,pending_count FROM (
      SELECT a,person=who::text OR c.terminal AND viewed OR EXISTS(SELECT FROM private.delayed_current_review_events e JOIN private.delayed_review_seen s ON s.event_id=e.id AND s.viewer=who
       WHERE e.child_id=c.id AND e.kind='attempt' AND e.actor::text=person AND e.round>=(a->>'round')::int) visible
      FROM jsonb_array_elements(coalesce(c.state->'attempts','[]')) a WHERE a->>'actor'=person
     ) visible_attempts;
    scores:=scores||jsonb_build_object(person,CASE WHEN pending_count>0 AND seen_count=0 THEN NULL ELSE shown END);
    pending_counts:=pending_counts||jsonb_build_object(person,least(pending_count,1));
    required:=CASE c.game_type WHEN 'tri-towers' THEN (c.config->>'stages')::int+CASE WHEN private.tri_towers_bonus_qualified_v2(pts,c.config) THEN (c.config->>'maxBonusStages')::int ELSE 0 END
     WHEN 'crib-lab' THEN 3 WHEN 'chucky-showdown' THEN 3
     WHEN 'quintzee' THEN private.quintzee_required_rounds(pts)
     WHEN 'boxdrop' THEN private.boxdrop_required_rounds(pts)
     WHEN 'mega-card-golf' THEN (c.config#>>'{course,holes}')::int
     ELSE greatest((c.config->>'rounds')::int,coalesce((c.state->>'round')::int,1)) END;
    progress:=progress||jsonb_build_object(person,CASE WHEN c.terminal OR next_round>required THEN 'Complete' ELSE 'Next Round: '||next_round END);
   END LOOP;
  END IF;

 item:=item||jsonb_build_object('reviewCount',(SELECT count(*) FROM private.delayed_current_review_events e
  WHERE e.child_id=c.id AND c.terminal AND e.kind='child'
   AND private.delayed_take_two_review_allowed(ROW(e.*)::private.delayed_review_events,who)
   AND NOT EXISTS(SELECT FROM private.delayed_review_seen seen WHERE seen.event_id=e.id AND seen.viewer=who)));
 lineup:=lineup||jsonb_build_array(item||CASE WHEN c.game_type='five-alive' THEN jsonb_build_object('playable',h->>'status'='active' AND NOT (h->>'held')::boolean AND c.expires_at>statement_timestamp() AND private.five_alive_or_actor(c,who),'opponentPlayable',h->>'status'='active' AND NOT (h->>'held')::boolean AND c.expires_at>statement_timestamp() AND private.five_alive_or_actor(c,CASE WHEN who::text=(h->>'organizer') THEN (h->>'opponent')::uuid ELSE (h->>'organizer')::uuid END)) ELSE '{}'::jsonb END||jsonb_build_object('scores',scores,'holeResults',CASE WHEN c.game_type='mega-card-golf' THEN (SELECT coalesce(jsonb_agg(jsonb_build_object('actor',a->>'actor','hole',a->'round','score',a->'score','at',a->'at')),'[]') FROM jsonb_array_elements(coalesce(c.state->'attempts','[]')) a WHERE a->>'actor'=who::text OR EXISTS(SELECT FROM private.delayed_current_review_events e JOIN private.delayed_review_seen seen ON seen.event_id=e.id AND seen.viewer=who WHERE e.child_id=c.id AND e.actor::text=a->>'actor' AND e.round>=(a->>'round')::int)) END,'pendingResults',pending_counts,'progress',progress,'bagCount',CASE WHEN c.game_type='ptown-words' THEN jsonb_array_length(c.state->'bag') END,'reviewId',f,'viewed',viewed,'result',CASE WHEN viewed THEN item->'result' ELSE NULL END));
 END LOOP;
 RETURN h||jsonb_build_object('lineup',lineup,'unsettled',(SELECT coalesce(sum(stake),0) FROM private.delayed_children WHERE match_id=p_match AND NOT terminal),
  'reviewsComplete',private.delayed_reviews_complete(p_match,who),'finaleViewed',EXISTS(SELECT FROM private.delayed_current_finale_seen WHERE match_id=p_match AND viewer=who));
END $function$

CREATE OR REPLACE FUNCTION public.delayed_load(p_child uuid, p_actor uuid, p_request uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c private.delayed_children;m private.delayed_matches;r private.delayed_commands;
BEGIN
 IF p_actor IS NOT NULL THEN PERFORM private.require_account_enabled(p_actor); END IF;
 PERFORM private.delayed_words_check_health();
 PERFORM pg_advisory_xact_lock_shared(731907241);
 SELECT * INTO STRICT m FROM private.delayed_matches WHERE id=(SELECT match_id FROM private.delayed_children WHERE id=p_child) FOR UPDATE;
 SELECT * INTO STRICT c FROM private.delayed_children WHERE id=p_child FOR UPDATE;
 IF p_actor IS NOT NULL THEN
  PERFORM private.delayed_actor(p_actor);
  IF p_actor NOT IN(m.organizer,m.opponent) THEN RAISE EXCEPTION 'delayed:not_authorized' USING ERRCODE='42501'; END IF;
 END IF;
 IF c.game_type NOT IN('run21','tri-towers','quintzee','boxdrop','mega-card-golf','take-two','crib-lab','chucky-showdown') OR EXISTS(SELECT FROM private.delayed_removals WHERE match_id=m.id) THEN RAISE EXCEPTION 'delayed:removed_or_unavailable';END IF;
 IF m.status NOT IN('active','settled') THEN RAISE EXCEPTION 'delayed:not_active';END IF;
 SELECT * INTO r FROM private.delayed_commands WHERE actor=p_actor AND request_id=p_request;
 RETURN private.delayed_child_record(c)||jsonb_build_object('reviewed',(SELECT coalesce(jsonb_agg(e.actor::text||':'||e.round),'[]') FROM private.delayed_current_review_events e WHERE e.child_id=c.id AND e.kind='attempt' AND EXISTS(SELECT FROM private.delayed_current_review_events acknowledged JOIN private.delayed_review_seen s ON s.event_id=acknowledged.id AND s.viewer=p_actor WHERE acknowledged.child_id=e.child_id AND acknowledged.actor=e.actor AND acknowledged.kind='attempt' AND acknowledged.round>=e.round)),'receipt',CASE WHEN r.request_id IS NOT NULL THEN to_jsonb(r) END);
END $function$

CREATE OR REPLACE FUNCTION public.delayed_recovery_claim(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE s private.delayed_recovery_state;records jsonb;
BEGIN
 PERFORM private.delayed_words_check_health();
 PERFORM pg_advisory_xact_lock_shared(731907241);
 PERFORM 1 FROM private.delayed_words_health WHERE singleton FOR UPDATE;
 SELECT * INTO STRICT s FROM private.delayed_recovery_state WHERE singleton FOR UPDATE;
 IF p_token IS NULL OR s.token IS DISTINCT FROM p_token OR s.claimed OR s.expires_at<=clock_timestamp() OR NOT s.enabled
 THEN RAISE EXCEPTION 'delayed:recovery_denied';END IF;
 UPDATE private.delayed_recovery_state SET claimed=true WHERE singleton;
 SELECT coalesce(jsonb_agg(private.delayed_child_record(c::private.delayed_children)),'[]') INTO records FROM (
  SELECT c.* FROM private.delayed_children c JOIN private.delayed_matches m ON m.id=c.match_id
  WHERE NOT c.terminal AND m.status='active' AND NOT private.delayed_held(m.id) AND c.game_type NOT IN('ptown-words','chess')
   AND least(c.expires_at,c.gameplay_due_at)<=clock_timestamp()
  ORDER BY least(c.expires_at,c.gameplay_due_at),c.id LIMIT 20) c;
 RETURN records;
END $function$

CREATE OR REPLACE FUNCTION public.delayed_respond(p_match uuid, p_request uuid, p_offer_hash text, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor_i uuid:=auth.uid(); m private.delayed_matches; receipt private.delayed_requests; fingerprint jsonb;
 c private.delayed_children; first_actor uuid; at_time timestamptz; response jsonb; dealt jsonb;
BEGIN
 PERFORM private.delayed_words_check_health();
 PERFORM pg_advisory_xact_lock_shared(731907241);
 PERFORM private.delayed_actor(actor_i);
 IF p_request IS NULL THEN RAISE EXCEPTION 'delayed:request_required'; END IF;
 fingerprint:=jsonb_build_object('op',p_action,'match',p_match,'hash',p_offer_hash);
 PERFORM pg_advisory_xact_lock(hashtextextended(actor_i::text||p_request::text,317));
 SELECT * INTO receipt FROM private.delayed_requests WHERE delayed_requests.actor=actor_i AND request_id=p_request;
 IF FOUND THEN IF receipt.fingerprint IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'delayed:request_conflict'; END IF; RETURN receipt.response; END IF;
 SELECT * INTO STRICT m FROM private.delayed_matches WHERE id=p_match FOR UPDATE;
 IF p_action IS NULL OR p_action NOT IN('accept','decline','cancel') OR
  actor_i IS DISTINCT FROM (CASE WHEN p_action='cancel' THEN m.organizer ELSE m.opponent END) THEN RAISE EXCEPTION 'delayed:not_authorized' USING ERRCODE='42501'; END IF;
 IF m.status<>'invited' OR p_offer_hash IS DISTINCT FROM m.offer_hash THEN RAISE EXCEPTION 'delayed:offer_changed'; END IF;
 IF p_action='cancel' THEN
  PERFORM private.delayed_delete_pending_invitation(m.id);
  response:=jsonb_build_object('status','cancelled','deleted',true);
  INSERT INTO private.delayed_requests VALUES(actor_i,p_request,fingerprint,m.id,response);
  RETURN response;
 END IF;
 at_time:=clock_timestamp();
 IF at_time>=m.expires_at THEN UPDATE private.delayed_matches SET status='expired',revision=revision+1 WHERE id=m.id; response:='{"status":"expired"}';
 ELSIF p_action='accept' THEN
  PERFORM private.delayed_actor(m.organizer);
  IF EXISTS(SELECT FROM public.system_settings WHERE key='maintenance_mode' AND value->>'enabled'='true') THEN RAISE EXCEPTION 'delayed:maintenance'; END IF;
  IF NOT EXISTS(SELECT FROM private.delayed_release WHERE singleton AND admission_enabled) OR private.delayed_held(m.id) THEN RAISE EXCEPTION 'delayed:admission_closed'; END IF;
  IF EXISTS(SELECT FROM private.delayed_children WHERE match_id=m.id AND game_type='mega-card-golf') AND NOT ((SELECT async_enabled FROM private.mega_competition_release WHERE singleton) OR private.mega_test_async_allowed(m.organizer,m.opponent,NULL,m.id,m.real_money)) THEN RAISE EXCEPTION 'delayed:admission_closed';END IF;
 IF m.real_money AND NOT EXISTS(SELECT FROM private.delayed_release WHERE singleton AND real_qualified) THEN RAISE EXCEPTION 'delayed:real_money_closed';END IF;
  IF NOT private.delayed_multi_enabled() AND ((SELECT count(*) FROM private.delayed_children WHERE match_id=m.id)<>1 OR EXISTS(SELECT FROM private.delayed_children WHERE match_id=m.id AND game_type<>'ptown-words')) THEN RAISE EXCEPTION 'delayed:scope_closed';END IF;
  IF EXISTS(SELECT FROM private.delayed_children WHERE match_id=m.id AND game_type='take-two')
   AND NOT (SELECT enabled FROM private.delayed_take_two_release WHERE singleton) THEN RAISE EXCEPTION 'delayed:admission_closed';END IF;
  FOR c IN SELECT * FROM private.delayed_children WHERE match_id=m.id ORDER BY ordinal FOR UPDATE LOOP
   IF c.game_type NOT IN('five-alive','chess','ptown-words','run21','tri-towers','quintzee','boxdrop','mega-card-golf','take-two','crib-lab','chucky-showdown') THEN RAISE EXCEPTION 'delayed:scope_closed';END IF;
   IF c.game_type IN('crib-lab','chucky-showdown') AND NOT EXISTS(SELECT FROM private.originals_release WHERE game=c.game_type AND async_enabled AND (NOT m.real_money OR async_real_qualified)) THEN RAISE EXCEPTION 'originals:async_closed';END IF;
   dealt:=NULL;
   IF c.game_type='five-alive' THEN
    IF NOT EXISTS(SELECT FROM private.five_alive_release WHERE singleton AND async_enabled AND (NOT m.real_money OR async_real_qualified)) THEN RAISE EXCEPTION 'delayed:admission_closed';END IF;
    dealt:=private.five_alive_async_deal(c.id,m.organizer,m.opponent,c.config->>'poolVersion');
   END IF;
   IF c.game_type='ptown-words' THEN dealt:=private.ptown_words_deal(jsonb_build_object('rules',c.config,'players',(SELECT jsonb_agg(jsonb_build_object('id',p.id,'userId',p.id,'name',p.username,'seat',CASE WHEN p.id=m.organizer THEN 1 ELSE 2 END,'isBot',false) ORDER BY CASE WHEN p.id=m.organizer THEN 1 ELSE 2 END) FROM public.profiles p WHERE p.id IN(m.organizer,m.opponent))),floor(extract(epoch FROM at_time)*1000)::bigint);
   first_actor:=(dealt->'players'->(dealt->>'turnIndex')::int->>'id')::uuid;
   ELSE first_actor:=CASE WHEN get_byte(extensions.gen_random_bytes(1),0)%2=0 THEN m.organizer ELSE m.opponent END;END IF;
   IF c.game_type='take-two' THEN
    INSERT INTO private.delayed_take_two_deals(child_id,round,deck)
    SELECT c.id,r,private.take_two_shuffle() FROM generate_series(1,3) r;
   END IF;
   IF c.game_type='chess' THEN
    IF NOT private.chess_actor_allowed(m.organizer) OR NOT private.chess_actor_allowed(m.opponent) OR NOT EXISTS(SELECT FROM private.chess_release WHERE singleton AND enabled AND admission_enabled AND async_enabled AND (NOT m.real_money OR real_qualified)) THEN RAISE EXCEPTION 'chess:async_closed';END IF;
    dealt:=private.chess_seed(jsonb_build_object('identity',jsonb_build_object('sessionId',m.id,'dealerGameId',c.id,'roundId',c.id),'players',(SELECT jsonb_agg(jsonb_build_object('id',p.id,'userId',p.id,'name',p.username,'seat',CASE WHEN p.id=first_actor THEN 1 ELSE 2 END,'isBot',false) ORDER BY CASE WHEN p.id=first_actor THEN 1 ELSE 2 END) FROM public.profiles p WHERE p.id IN(m.organizer,m.opponent))),'async',floor(extract(epoch FROM at_time)*1000)::bigint);
   END IF;
   UPDATE private.delayed_children SET state=dealt,starter=first_actor,actor=first_actor,segment=1,revision=1,
    available_at=at_time,last_call_at=at_time+interval '24 hours',expires_at=at_time+interval '36 hours' WHERE id=c.id;
  END LOOP;
  UPDATE private.delayed_matches SET status='active',accepted_at=at_time,revision=revision+1 WHERE id=m.id;
  response:='{"status":"active"}';
 ELSE
  UPDATE private.delayed_matches SET status=CASE p_action WHEN 'decline' THEN 'declined' ELSE 'cancelled' END,revision=revision+1 WHERE id=m.id;
  response:=jsonb_build_object('status',CASE p_action WHEN 'decline' THEN 'declined' ELSE 'cancelled' END);
 END IF;
 INSERT INTO private.delayed_requests VALUES(actor_i,p_request,fingerprint,m.id,response);
 PERFORM private.delayed_notify(m.id); RETURN response;
END $function$

CREATE OR REPLACE FUNCTION private.delayed_quintzee_missed_turn(c private.delayed_children, m private.delayed_matches)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE s jsonb:=c.state;b jsonb;ids jsonb;at_ms bigint:=floor(extract(epoch FROM c.expires_at)*1000);turn_i int;round_i int;done boolean:=false;winner uuid;who text;total bigint;
BEGIN
 IF c.gameplay_due_at IS NOT NULL THEN RAISE EXCEPTION 'delayed:entered_round';END IF;
 IF s IS NULL THEN
  ids:=jsonb_build_array(c.starter,CASE WHEN c.starter=m.organizer THEN m.opponent ELSE m.organizer END);
  s:=jsonb_build_object('version','delayed/1','game','quintzee','child',c.id,'players',ids,'round',1,'turn',0,
   'totals',jsonb_build_object(m.organizer::text,0,m.opponent::text,0),'attempts','[]'::jsonb,'board',NULL,'deck',NULL,'completed',false,'winner',NULL,'segmentStartedAt',NULL);
 END IF;
 IF s->'players'->>((s->>'turn')::int) IS DISTINCT FROM c.actor::text OR nullif(s->'board','null') IS NOT NULL THEN RAISE EXCEPTION 'delayed:missed_turn_identity';END IF;
 -- The unchanged rule core produces the empty round and its zero-score result.
 b:=public.delayed_board_core('quintzee','deal',c.config,(s->'totals'->>c.actor::text)::bigint,NULL,NULL,NULL,at_ms-(c.config->>'durationMs')::bigint-(c.config->>'introMs')::bigint);
 b:=public.delayed_board_core('quintzee','reduce',c.config,0,b,'tick',ARRAY[]::int[],(b->>'deadline')::bigint);
 IF b->>'phase'<>'stage_complete' OR (b->>'score')::bigint<>(s->'totals'->>c.actor::text)::bigint THEN RAISE EXCEPTION 'delayed:empty_round_score';END IF;
 s:=s||jsonb_build_object('attempts',(s->'attempts')||jsonb_build_array(jsonb_build_object('actor',c.actor,'round',(s->>'round')::int,'score',0,'at',at_ms,'board',b,'availabilityExpired',true)), 'board',NULL,'deck',NULL,'segmentStartedAt',NULL);
 turn_i:=(s->>'turn')::int+1;round_i:=(s->>'round')::int;
 IF turn_i=2 THEN turn_i:=0;round_i:=round_i+1;END IF;
 WHILE round_i>(c.config->>'rounds')::int LOOP
  IF round_i>(c.config->>'maxRounds')::int THEN done:=true;EXIT;END IF;
  who:=s->'players'->>turn_i;total:=(s->'totals'->>who)::bigint;
  EXIT WHEN round_i<=(public.delayed_board_core('quintzee','rounds',p_score=>total))::int;
  turn_i:=turn_i+1;IF turn_i=2 THEN turn_i:=0;round_i:=round_i+1;END IF;
 END LOOP;
 IF done THEN
  IF (s->'totals'->>(s->'players'->>0))::bigint<>(s->'totals'->>(s->'players'->>1))::bigint THEN
   winner:=CASE WHEN (s->'totals'->>(s->'players'->>0))::bigint>(s->'totals'->>(s->'players'->>1))::bigint THEN (s->'players'->>0)::uuid ELSE (s->'players'->>1)::uuid END;
  END IF;
 END IF;
 s:=s||jsonb_build_object('turn',turn_i,'round',round_i,'completed',done,'winner',winner);
 UPDATE private.delayed_children SET state=s,actor=(s->'players'->>turn_i)::uuid,revision=revision+1,segment=segment+1,
  available_at=clock_timestamp(),started_at=NULL,gameplay_due_at=NULL WHERE id=c.id RETURNING * INTO c;
 UPDATE private.delayed_matches SET revision=revision+1 WHERE id=m.id;
 IF done THEN PERFORM private.delayed_record_outcome(c.id,c.revision,CASE WHEN winner IS NULL THEN 'draw' ELSE 'normal' END,winner,jsonb_build_object('rules',c.config,'finalState',s));
 ELSE PERFORM private.delayed_notify(m.id);END IF;
END $function$

CREATE OR REPLACE FUNCTION private.five_alive_or_actor(c private.delayed_children, p_actor uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE game jsonb;round_i integer;idx integer;
BEGIN
 IF c.terminal OR p_actor IS NULL THEN RETURN false;END IF;
 IF c.game_type<>'five-alive' THEN RETURN c.actor=p_actor;END IF;
 game:=c.state->'fiveAlive';round_i:=(game->>'current')::integer;
 IF round_i IS NULL OR round_i NOT BETWEEN 0 AND 2 THEN RETURN false;END IF;
 idx:=CASE WHEN game->'players'->>0=p_actor::text THEN 0 WHEN game->'players'->>1=p_actor::text THEN 1 ELSE NULL END;
 IF idx IS NULL THEN RETURN false;END IF;
 RETURN coalesce((game->'rounds'->idx->round_i->>'completed')::boolean=false,false);
END $function$

CREATE OR REPLACE FUNCTION private.optional_bonus_winner(game text, cfg jsonb, players jsonb, totals jsonb, rounds jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE player text; qualified text[]:='{}'; amount bigint; floor_i bigint; eligible boolean;
BEGIN
 IF jsonb_array_length(players)<>2 OR game NOT IN('tri-towers','quintzee','boxdrop','eleven-up','royal-flash') THEN RETURN NULL;END IF;
 IF cfg->>'version' IS NULL OR
  game='quintzee' AND cfg->>'version' NOT IN('quintzee/1','quintzee/2','quintzee/3') OR
  game='boxdrop' AND cfg->>'version'<>'boxdrop/1' OR
  game='eleven-up' AND cfg->>'version' NOT IN('eleven-up/1','eleven-up/2','eleven-up/3') OR
  game='royal-flash' AND cfg->>'version' NOT IN('royal-flash/1','royal-flash/2','royal-flash/3') THEN RETURN NULL;END IF;
 FOR player IN SELECT jsonb_array_elements_text(players) LOOP
  -- Both main rounds must be authoritative and complete; no guessed eligibility.
  IF (SELECT array_agg(DISTINCT (r->>'round')::integer ORDER BY (r->>'round')::integer)
      FROM jsonb_array_elements(rounds) r WHERE r->>'actor'=player) IS DISTINCT FROM ARRAY[1,2] THEN RETURN NULL;END IF;
  amount:=(totals->>player)::bigint;
  IF amount IS NULL OR amount<0 THEN RETURN NULL;END IF;
  eligible:=CASE game WHEN 'tri-towers' THEN private.tri_towers_bonus_qualified_v2(amount,cfg)
   WHEN 'quintzee' THEN private.quintzee_required_rounds(amount)=3
   WHEN 'boxdrop' THEN private.boxdrop_required_rounds(amount)=3
   WHEN 'eleven-up' THEN private.eleven_up_bonus_qualified(amount,cfg)
   WHEN 'royal-flash' THEN private.royal_flash_bonus_qualified(amount,cfg) END;
  IF eligible THEN qualified:=array_append(qualified,player);END IF;
 END LOOP;
 IF cardinality(qualified)<>1 THEN RETURN NULL;END IF;
 player:=qualified[1];amount:=(totals->>player)::bigint;
 -- TriTowers can subtract for each of the 23 undealt stock cards. Even the
 -- worst legal bonus must leave a strict lead; qualification alone is insufficient.
 IF game='tri-towers' THEN
  IF cfg->>'version' NOT IN('tri-towers/2','tri-towers/3','tri-towers/4','tri-towers/5') OR (cfg->>'drawPenalty')::bigint<0 OR NOT(cfg?'drawPenalty') THEN RETURN NULL;END IF;
  floor_i:=greatest(0,amount-23*(cfg->>'drawPenalty')::bigint);
 ELSE
  -- Quintzee, Boxdrop and Royal Flash add nonnegative round points. 11 Up starts
  -- with a full rack: every penalized refill spends a previously earned removal
  -- value of that exact slot, so a round cannot consume the pre-round total.
  floor_i:=amount;
 END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements_text(players) p WHERE p<>player AND floor_i<=(totals->>p)::bigint) THEN RETURN NULL;END IF;
 RETURN player;
END $function$

CREATE OR REPLACE FUNCTION public.delayed_originals_core(p_child uuid, p_operation text, p_round integer DEFAULT NULL::integer, p_score bigint DEFAULT 0, p_board jsonb DEFAULT NULL::jsonb, p_action text DEFAULT NULL::text, p_items integer[] DEFAULT NULL::integer[], p_at bigint DEFAULT NULL::bigint, p_level integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c private.delayed_children; deck_i jsonb;
BEGIN
 SELECT * INTO STRICT c FROM private.delayed_children WHERE id=p_child;
 IF c.game_type NOT IN('crib-lab','chucky-showdown') THEN RAISE EXCEPTION 'originals:child';END IF;
 IF p_operation='visible' THEN RETURN private.originals_visible(c.game_type,p_board,p_at);END IF;
 IF p_operation='deal' AND c.game_type='crib-lab' AND (c.config->>'sharedDeck')::boolean THEN
  INSERT INTO private.originals_async_decks VALUES(c.id,p_round,private.cribbage_new_deck()) ON CONFLICT DO NOTHING;
  SELECT deck INTO STRICT deck_i FROM private.originals_async_decks WHERE child_id=c.id AND round=p_round;
 END IF;
 RETURN private.originals_board(c.game_type,p_operation,c.config,p_round,p_score,p_board,p_at,p_action,p_items,p_level,deck_i);
END $function$

CREATE OR REPLACE FUNCTION public.delayed_review_ack(p_event uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE e private.delayed_review_events;m private.delayed_matches;who uuid:=auth.uid();inserted integer;
BEGIN
 SELECT * INTO STRICT e FROM private.delayed_current_review_events WHERE id=p_event;
 SELECT * INTO m FROM private.delayed_matches WHERE id=e.match_id AND who IN(organizer,opponent) FOR UPDATE;
 IF NOT FOUND OR EXISTS(SELECT FROM private.delayed_removals WHERE match_id=m.id) THEN RAISE EXCEPTION 'delayed:not_found' USING ERRCODE='42501';END IF;
 IF NOT private.delayed_take_two_review_allowed(e,who) THEN RAISE EXCEPTION 'delayed:review_unavailable' USING ERRCODE='42501';END IF;
 INSERT INTO private.delayed_review_seen(event_id,viewer) VALUES(e.id,who) ON CONFLICT DO NOTHING;
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted=0 THEN RETURN;END IF;
 PERFORM private.delayed_notify(m.id);
 UPDATE private.delayed_matches SET revision=revision+1 WHERE id=m.id;
END $function$

CREATE OR REPLACE FUNCTION public.delayed_review_begin(p_event uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE e private.delayed_review_events;who uuid:=auth.uid();started timestamptz;
BEGIN
 SELECT * INTO e FROM private.delayed_current_review_events WHERE id=p_event;
 IF NOT FOUND OR NOT EXISTS(SELECT FROM private.delayed_matches WHERE id=e.match_id AND who IN(organizer,opponent)) OR EXISTS(SELECT FROM private.delayed_removals WHERE match_id=e.match_id)
 THEN RAISE EXCEPTION 'delayed:not_found' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM private.delayed_matches WHERE id=e.match_id FOR UPDATE;
 IF EXISTS(SELECT FROM private.delayed_removals WHERE match_id=e.match_id) THEN RAISE EXCEPTION 'delayed:not_found' USING ERRCODE='42501';END IF;
 IF NOT private.delayed_take_two_review_allowed(e,who) THEN RAISE EXCEPTION 'delayed:review_unavailable' USING ERRCODE='42501';END IF;
 INSERT INTO private.delayed_review_playback(event_id,viewer) VALUES(e.id,who)
 ON CONFLICT(event_id,viewer) DO UPDATE SET lease_until=clock_timestamp()+interval '5 minutes'
 RETURNING started_at INTO started;
 RETURN jsonb_build_object('elapsed',greatest(0,floor(extract(epoch FROM clock_timestamp()-started)*1000)),'seen',EXISTS(SELECT FROM private.delayed_review_seen WHERE event_id=e.id AND viewer=who));
END $function$

CREATE OR REPLACE FUNCTION public.delayed_take_two_core(p_child uuid, p_operation text, p_round integer DEFAULT NULL::integer, p_score bigint DEFAULT 0, p_board jsonb DEFAULT NULL::jsonb, p_action text DEFAULT NULL::text, p_items integer[] DEFAULT NULL::integer[], p_at bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c private.delayed_children;deck_i jsonb;
BEGIN
 SELECT * INTO STRICT c FROM private.delayed_children WHERE id=p_child;
 IF c.game_type<>'take-two' OR c.config IS DISTINCT FROM private.take_two_rules('take-two/2') THEN RAISE EXCEPTION 'take_two:child';END IF;
 CASE p_operation
 WHEN 'deal' THEN
  SELECT deck INTO STRICT deck_i FROM private.delayed_take_two_deals WHERE child_id=c.id AND round=p_round;
  RETURN private.take_two_board_from_deck(jsonb_build_object('rules',c.config,'stage',p_round,'score',p_score,'highScore',0),p_at,deck_i);
 WHEN 'reduce' THEN
  IF p_board->'rules' IS DISTINCT FROM c.config THEN RAISE EXCEPTION 'take_two:rules';END IF;
  RETURN private.take_two_board_reduce(p_board,p_action,p_items,p_at);
 WHEN 'visible' THEN RETURN private.take_two_visible(p_board)-'activePlayerId';
 ELSE RAISE EXCEPTION 'delayed:invalid_core_operation';END CASE;
END $function$

CREATE OR REPLACE FUNCTION private.mega_delayed_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE attempt jsonb;person text;prior jsonb;i integer:=0;total bigint;count_i integer;low bigint;winners jsonb;
BEGIN
 IF NEW.game_type<>'mega-card-golf' OR NEW.state IS NULL THEN RETURN NEW;END IF;
 IF NEW.config IS DISTINCT FROM OLD.config OR NEW.match_id IS DISTINCT FROM OLD.match_id OR NEW.stake IS DISTINCT FROM OLD.stake THEN RAISE EXCEPTION 'mega:immutable_configuration';END IF;
 IF NEW.state->>'child' IS DISTINCT FROM NEW.id::text OR NEW.state->>'game' IS DISTINCT FROM 'mega-card-golf' OR NEW.state->'players' IS DISTINCT FROM coalesce(OLD.state->'players',jsonb_build_array(NEW.starter,CASE WHEN NEW.starter=(SELECT organizer FROM private.delayed_matches WHERE id=NEW.match_id) THEN (SELECT opponent FROM private.delayed_matches WHERE id=NEW.match_id) ELSE (SELECT organizer FROM private.delayed_matches WHERE id=NEW.match_id) END)) THEN RAISE EXCEPTION 'mega:invalid_identity';END IF;
 IF NEW.state->'board' IS NOT NULL AND NEW.state->'board'<>'null'::jsonb THEN
  SELECT value->'board' INTO prior FROM jsonb_array_elements(coalesce(OLD.state->'attempts','[]')) WHERE value->>'actor'=NEW.actor::text ORDER BY (value->>'round')::integer DESC LIMIT 1;
  PERFORM private.mega_assert_board(NEW.state->'board',NEW.config,CASE WHEN OLD.state->'board'<>'null'::jsonb THEN OLD.state->'board' ELSE prior END);
 END IF;
 FOR attempt IN SELECT value FROM jsonb_array_elements(NEW.state->'attempts') LOOP
  i:=i+1;
  IF i<=jsonb_array_length(coalesce(OLD.state->'attempts','[]')) THEN
   IF attempt IS DISTINCT FROM OLD.state->'attempts'->(i-1) THEN RAISE EXCEPTION 'mega:immutable_hole';END IF;
  ELSE
   IF attempt->>'actor' IS DISTINCT FROM OLD.actor::text OR (attempt->>'round')::integer IS DISTINCT FROM coalesce((OLD.state->>'round')::integer,1) THEN RAISE EXCEPTION 'mega:invalid_turn';END IF;
   PERFORM private.mega_assert_board(attempt->'board',NEW.config,OLD.state->'board');
   IF (attempt->>'score')::bigint IS DISTINCT FROM (attempt#>>'{board,results,-1,score}')::bigint OR attempt#>>'{board,phase}' IS DISTINCT FROM 'scoring' THEN RAISE EXCEPTION 'mega:invalid_hole_score';END IF;
  END IF;
 END LOOP;
 IF i<jsonb_array_length(coalesce(OLD.state->'attempts','[]')) OR i>jsonb_array_length(coalesce(OLD.state->'attempts','[]'))+1 THEN RAISE EXCEPTION 'mega:invalid_transition';END IF;
 FOR person IN SELECT jsonb_array_elements_text(NEW.state->'players') LOOP
  SELECT coalesce(sum((value->>'score')::bigint),0),count(*) INTO total,count_i FROM jsonb_array_elements(NEW.state->'attempts') WHERE value->>'actor'=person;
  IF (NEW.state->'totals'->>person)::bigint IS DISTINCT FROM total OR count_i>(NEW.config#>>'{course,holes}')::integer THEN RAISE EXCEPTION 'mega:invalid_total';END IF;
 END LOOP;
 IF (NEW.state->>'completed')::boolean THEN
  IF i<>2*(NEW.config#>>'{course,holes}')::integer THEN RAISE EXCEPTION 'mega:incomplete_course';END IF;
  SELECT min(value::bigint) INTO low FROM jsonb_each_text(NEW.state->'totals');
  SELECT jsonb_agg(key) INTO winners FROM jsonb_each_text(NEW.state->'totals') WHERE value::bigint=low;
  IF NEW.state->>'winner' IS DISTINCT FROM (CASE WHEN jsonb_array_length(winners)=1 THEN winners->>0 END) THEN RAISE EXCEPTION 'mega:invalid_winner';END IF;
 END IF;RETURN NEW;
END $function$
